  const [error, setError] = useState(''), [productId, setProductId] = useState(''), [onsiteConfirmed, setOnsiteConfirmed] = useState(false), [onsiteAmount, setOnsiteAmount] = useState(''), [onsiteReference, setOnsiteReference] = useState(''), [onsiteNote, setOnsiteNote] = useState('')
